enum class GroupCallStage {
    CONCURRENCY_REJECTED,
    CIRCUIT_OPEN,
    CONNECT_TIMEOUT,
    READ_TIMEOUT,
    UPSTREAM_5XX,
    UPSTREAM_CONTRACT_ERROR,
    RETRY_BUDGET_EXCEEDED,
